#!/bin/sh
# upper.sh WORD... : print each word in upper case
[ $# -gt 0 ] || { echo "usage: upper.sh WORD..." >&2; exit 2; }
for w in "$@"; do
  printf '%s\n' "$w" | tr 'a-z' 'A-Z'
done

