#!/bin/bash
# table.sh NAME QTY [NAME QTY...] : print a TAB-separated table with the header "ITEM<TAB>QTY"
[ $(($# % 2)) -eq 0 ] && [ $# -gt 0 ] || { echo "usage: table.sh NAME QTY [NAME QTY...]" >&2; exit 2; }
