#!/bin/sh
# revlines.sh FILE : print the lines of FILE last to first as "N: text" where N is the original line number
[ $# -eq 1 ] && [ -r "$1" ] || { echo "usage: revlines.sh FILE" >&2; exit 2; }
awk '{ l[NR] = $0 } END { for (i = NR; i >= 1; i--) print i ": " l[i] }' "$1"

