#!/bin/sh
# joinargs.sh SEP ITEM... : print the items joined with the single character SEP
[ $# -ge 1 ] || { echo "usage: joinargs.sh SEP ITEM..." >&2; exit 2; }
sep=$1
shift
[ "${#sep}" -le 1 ] || { echo "error: SEP must be one character" >&2; exit 2; }
IFS=$sep
printf '%s\n' "$*"

